import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { LogOut } from 'lucide-react';

// --- Configuration ---
const API_BASE_URL = 'http://localhost:9091/api/medicines';

// --- Utility Components (Minimal UI for brevity) ---

const MessageDisplay = ({ message, clearMessage }) => (
    message ? (
        <div className={`p-3 max-w-xl mx-auto mb-4 rounded-lg text-sm font-medium flex justify-between items-center ${
            message.type === 'error' ? 'bg-red-100 text-red-700' : 
            message.type === 'success' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700'
        }`}>
            {message.text}
            <button onClick={clearMessage} className="font-bold opacity-75 hover:opacity-100">&times;</button>
        </div>
    ) : null
);

// --- 1. Login Component ---
function Login({ onLogin, message }) {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const handleSubmit = (e) => { e.preventDefault(); onLogin(username, password); };

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
            <div className="bg-white p-6 rounded-xl shadow-lg w-full max-w-sm">
                <h2 className="text-2xl font-bold text-center text-indigo-700 mb-4">Login</h2>
                <div className="p-2 mb-3 rounded-lg text-xs bg-blue-100 text-blue-700">
                    Demo: `admin`/`pass` or `user`/`pass`
                </div>
                {message && message.type === 'error' && (
                    <div className="p-2 mb-3 rounded-lg text-xs bg-red-100 text-red-700">{message.text}</div>
                )}
                <form onSubmit={handleSubmit} className="space-y-3">
                    <input type="text" placeholder="Username" required value={username} onChange={e => setUsername(e.target.value)}
                        className="w-full px-3 py-2 border rounded" />
                    <input type="password" placeholder="Password" required value={password} onChange={e => setPassword(e.target.value)}
                        className="w-full px-3 py-2 border rounded" />
                    <button type="submit" className="w-full py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700">Login</button>
                </form>
            </div>
        </div>
    );
}

// --- 2. AdminDashboard Component (Minimal) ---
function AdminDashboard({ token, setMessage, onLogout }) {
    const [medicines, setMedicines] = useState([]);

    const fetchMedicines = useCallback(async () => {
        try {
            const response = await axios.get(`${API_BASE_URL}/api/admin/medicines`, { headers: { Authorization: `Bearer ${token}` } });
            setMedicines(response.data);
        } catch (error) {
            setMessage({ type: 'error', text: 'Admin fetch failed. Check backend URL.' });
            setMedicines([{id: 1, name: "Mock Admin Item", price: 99.99, stockQuantity: 5}]); // Minimal mock
        }
    }, [token, setMessage]);

    useEffect(() => { fetchMedicines(); }, [fetchMedicines]);

    return (
        <div className="p-6 max-w-4xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-indigo-700">Admin Dashboard</h2>
                <button onClick={onLogout} className="text-red-500 hover:text-red-700 flex items-center text-sm">
                    <LogOut className="w-4 h-4 mr-1"/>Logout
                </button>
            </div>
            <div className="bg-white p-4 rounded-lg shadow">
                <h3 className="text-lg font-semibold mb-2">Inventory List (Minimal)</h3>
                <ul className="space-y-1">
                    {medicines.map(med => (
                        <li key={med.id} className="flex justify-between p-2 bg-gray-50 rounded">
                            <span>{med.name}</span>
                            <span className="font-medium">${med.price?.toFixed(2) || 'N/A'} (Stock: {med.stockQuantity})</span>
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
}

// --- 3. UserShop Component (Minimal) ---
function UserShop({ token, setMessage, onLogout }) {
    const [medicines, setMedicines] = useState([]);

    const fetchMedicines = useCallback(async () => {
        try {
            const response = await axios.get(`${API_BASE_URL}/api/user/medicines`, { headers: { Authorization: `Bearer ${token}` } });
            setMedicines(response.data.filter(med => med.stockQuantity > 0));
        } catch (error) {
            setMessage({ type: 'error', text: 'User shop fetch failed. Check backend URL.' });
            setMedicines([{id: 1, name: "Mock User Item", price: 4.50, stockQuantity: 12}]); // Minimal mock
        }
    }, [token, setMessage]);

    useEffect(() => { fetchMedicines(); }, [fetchMedicines]);

    return (
        <div className="p-6 max-w-4xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-indigo-700">Pharmacy Shop</h2>
                <button onClick={onLogout} className="text-red-500 hover:text-red-700 flex items-center text-sm">
                    <LogOut className="w-4 h-4 mr-1"/>Logout
                </button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {medicines.map(med => (
                    <div key={med.id} className="bg-white p-4 rounded-lg shadow border-t-2 border-indigo-500">
                        <h3 className="font-semibold">{med.name}</h3>
                        <p className="text-xs text-gray-500 mb-2">Available</p>
                        <div className="flex justify-between items-center">
                            <span className="text-lg font-bold text-green-600">${med.price?.toFixed(2) || 'N/A'}</span>
                            <button className="px-3 py-1 bg-indigo-500 text-white text-sm rounded">Buy</button>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

// --- 4. Main App Component (App.js Logic) ---
const App = () => {
    const [role, setRole] = useState(null); // 'admin', 'user', or null
    const [token, setToken] = useState(null);
    const [message, setMessage] = useState(null);

    const handleLogin = (username, password) => {
        setMessage(null);
        if (username === 'admin' && password === 'pass') {
            setRole('admin');
            setToken('admin_token');
            setMessage({ type: 'success', text: 'Admin login successful.' });
        } else if (username === 'user' && password === 'pass') {
            setRole('user');
            setToken('user_token');
            setMessage({ type: 'success', text: 'User login successful.' });
        } else {
            setMessage({ type: 'error', text: 'Invalid credentials.' });
        }
    };

    const handleLogout = () => { setRole(null); setToken(null); setMessage({ type: 'info', text: 'Logged out.' }); };
    const clearMessage = () => setMessage(null);

    const renderContent = () => {
        if (!role) {
            return <Login onLogin={handleLogin} message={message} />;
        } else if (role === 'admin') {
            return <AdminDashboard token={token} setMessage={setMessage} onLogout={handleLogout} />;
        } else if (role === 'user') {
            return <UserShop token={token} setMessage={setMessage} onLogout={handleLogout} />;
        }
    };

    return (
        <div className="min-h-screen bg-gray-50 font-sans pt-8">
            <MessageDisplay message={message} clearMessage={clearMessage} />
            {renderContent()}
        </div>
    );
};

export default App;
